package sfz.batch.l06.demo

import org.apache.spark.sql.functions.col
import org.apache.spark.sql.functions.sum

/** Builds a query step by step and shows that nothing runs until the action at the end. */
fun main() {
    val spark = demoSpark("local[4]")
    spark.conf().set("spark.sql.adaptive.enabled", "false")      // the plain model; lesson 8 turns AQE back on
    demoPayments(spark)                                            // writes the files on the first run
    val log = JobLog(spark)
    log.clear()

    fun <T> step(label: String, block: () -> T): T {
        val t0 = System.nanoTime()
        val result = block()
        println("%-32s %7.1f ms   so far: %s".format(label, (System.nanoTime() - t0) / 1e6, log.summary()))
        return result
    }
    val payments = step("read the Parquet files") { spark.read().parquet("build/l05/payments") }
    val captured = step("where(status = CAPTURED)") { payments.where(col("status").equalTo("CAPTURED")) }
    val euros = step("withColumn(amount_eur)") { captured.withColumn("amount_eur", col("amount_cents").divide(100)) }
    val totals = step("groupBy(merchant_id).agg(sum)") { euros.groupBy("merchant_id").agg(sum("amount_eur").alias("total_eur")) }
    step("collect()  <- the action") { totals.collectAsList() }
    println()
    totals.explain("extended")
    spark.stop()
}

package sfz.batch.l06.demo

import org.apache.spark.TaskContext
import org.apache.spark.api.java.function.MapPartitionsFunction
import org.apache.spark.sql.Encoders

/**
 * Runs one stage of 8 tasks, each of which works for 300 ms, first with 2 task slots and then
 * with 4. Every task reports its partition and when it started; tasks that started together are
 * one wave.
 */
fun main() {
    val tasks = 8                                               // try 9
    for (slots in listOf(2, 4)) {
        val spark = demoSpark("local[$slots]")
        val task = MapPartitionsFunction<Long, String> { _ ->
            val start = System.currentTimeMillis()
            Thread.sleep(300)                                   // pretend to read and filter 300 ms of data
            listOf("${TaskContext.getPartitionId()} $start").iterator()
        }
        spark.range(0, tasks.toLong(), 1, tasks).mapPartitions(task, Encoders.STRING()).collectAsList()   // warm-up: the first job pays for class loading
        val t0 = System.nanoTime()
        val started = spark.range(0, tasks.toLong(), 1, tasks).mapPartitions(task, Encoders.STRING()).collectAsList()
            .map { it.split(" ").let { (p, t) -> p.toInt() to t.toLong() } }
        val ms = (System.nanoTime() - t0) / 1_000_000
        println("local[$slots]: $tasks tasks of 300 ms each took $ms ms")
        val first = started.minOf { it.second }
        // tasks that started within 100 ms of each other ran side by side: one wave
        val waves = started.sortedBy { it.second }.fold(mutableListOf<MutableList<Pair<Int, Long>>>()) { acc, t ->
            if (acc.isEmpty() || t.second - acc.last().first().second > 100) acc += mutableListOf(t) else acc.last() += t
            acc
        }
        waves.forEachIndexed { i, w ->
            println("  wave %d starts at %4d ms: partitions %s".format(i + 1, w.first().second - first, w.map { it.first }.sorted().joinToString(", ")))
        }
        spark.stop()
    }
}

package sfz.batch.l06.demo

import org.apache.logging.log4j.Level
import org.apache.logging.log4j.core.config.Configurator
import org.apache.spark.TaskContext
import org.apache.spark.api.java.JavaSparkContext
import org.apache.spark.scheduler.SparkListener
import org.apache.spark.scheduler.SparkListenerTaskEnd
import scala.Tuple2

/**
 * Shows an RDD's lineage, then makes one task fail on its first attempt and watches Spark run that
 * task again from the same lineage. `local[2,4]` means 2 slots and up to 4 attempts per task.
 */
fun main() {
    val spark = demoSpark("local[2,4]")
    Configurator.setLevel("org.apache.spark.executor.Executor", Level.OFF)   // no stack trace for the planned crash
    val sc = JavaSparkContext(spark.sparkContext())
    spark.sparkContext().addSparkListener(object : SparkListener() {
        override fun onTaskEnd(taskEnd: SparkListenerTaskEnd) {
            val info = taskEnd.taskInfo()
            println("  stage %d, partition %d, attempt %d: %s".format(
                taskEnd.stageId(), info.index(), info.attemptNumber(), if (info.successful()) "ok" else "FAILED (${taskEnd.reason().javaClass.simpleName})"))
        }
    })

    // per merchant: how many payments, from 4 partitions of made-up (merchant, amount) pairs
    val counts = sc.parallelize((0 until 40_000).toList(), 4)
        .map { i ->
            // partition 2 crashes the first time it runs, like a machine that dies mid-task
            if (TaskContext.getPartitionId() == 2 && TaskContext.get().attemptNumber() == 0) error("executor lost")
            i % 5
        }
        .mapToPair { m -> Tuple2(m, 1) }
        .reduceByKey { a, b -> a + b }

    println("lineage:")
    println(counts.toDebugString().lines().joinToString("\n") { "  " + it.replace(Regex(""" at \w+\.kt:\d+ \[]"""), "") })
    println("running:")
    val result = counts.collectAsMap().toSortedMap()
    spark.sparkContext().listenerBus().waitUntilEmpty()
    println("result: $result")
    spark.stop()
}

