sealed interface Step
object Narrow : Step
data class Wide(val partitions: Int) : Step

fun tasksPerStage(inputPartitions: Int, steps: List<Step>): List<Int> {
    val stages = mutableListOf(inputPartitions)        // stage 1: one task per input partition
    for (step in steps) {
        if (step is Wide) stages += step.partitions      // a shuffle starts a new stage
    }
    return stages
}

// tasksPerStage(6, listOf(Narrow, Wide(10), Narrow, Wide(10))) == [6, 10, 10]: 3 stages, 26 tasks
// (a real join reads two inputs, so its first stages come in pairs; this model has one input)
